string solve(string input) {
    // 空字符串
    if (input.empty()) {
        return input;
    }
    string replaceStr = "(^|$|[,+])";
    string res = "";
    // 左括号数量
    int bracketCount  = 0;
​
    for (int i = 0; i < input.size(); i++) {
        char current = input[i];
        if (current == '[') {
            bracketCount++;
            res += string(1, current);
        } else if (current == ']'){
            bracketCount--;
            res+= string(1, current);
        // 下划线，不在括号内或者没被转义进行替换    
        }else if(current == '_' && (i == 0 || input[i-1] != '\\') && bracketCount == 0) {
            res += replaceStr;
        } else {
            res += string(1, current);
        }
    }
    return res;
}
