                bracketCount--;
                res.append(current);
            }
            // 下划线，不在括号内或者没被转义进行替换
            else if (current == '_' && (i == 0 || input.charAt(i - 1) != '\\') && bracketCount == 0) {
                res.append(replaceStr);
