package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
// 处理输入字符串
func solve(input string) string {
    if len(input) == 0 {
        return input
    }
​
    replaceStr := "(^|$|[,+])"
    var res strings.Builder
    bracketCount := 0 // 记录方括号的数量
​
    for i := 0; i < len(input); i++ {
        current := input[i]
​
        if current == '[' {
            bracketCount++
            res.WriteByte(current)
        } else if current == ']' {
            bracketCount--
            res.WriteByte(current)
        } else if current == '_' && (i == 0 || input[i-1] != '\\') && bracketCount == 0 {
            res.WriteString(replaceStr)
        } else {
            res.WriteByte(current)
        }
    }
​
    return res.String()
}
​
func main() {
    // 读取标准输入
    scanner := bufio.NewScanner(os.Stdin)
    if scanner.Scan() {
        input := scanner.Text()
        fmt.Println(solve(input))
    }
}
